      c.showEta = false;
      c.showZone = false;
      c.showCod = false;
      c.showReturnPolicy = false;
      c.showCutoffTime = false;
      c.showDeliveryDays = false;
      c.showDeliveryDate = false;
      c.showCountdown = false;
      c.showDeliveryFee = false;
