    return c;
  }, [cfg, widgetFullCustom, showEtaCodReturn]);

  const css = useMemo(() => buildWidgetCss(wid, effectiveCfg), [wid, effectiveCfg]);

  const resultMessage =
    previewState === "success" ? cfg.successMessage :
